1	#!/usr/bin/env node
2	/**
3	 * Generates `src/proto/` from the authoritative protobuf contract in
4	 * `crates/aion-proto-generated/proto/`.
5	 *
6	 * Why this exists as an importable module rather than an inline npm command:
7	 * the checked-in stubs drifted from the wire contract for months without
8	 * anyone noticing, because the only regeneration recipe was an inline `protoc`
9	 * invocation pointing at a directory (`crates/aion-proto/proto`) that had been
10	 * deleted, and nothing ever compared the committed output against a fresh
11	 * generation. `src/proto-contract.test.ts` imports the exports below and byte-
12	 * compares, so the drift is caught by the ordinary test run rather than by a
13	 * ritual nobody performs.
14	 *
15	 * CLI:
16	 *   node scripts/generate-proto.mjs           rewrite src/proto/ in place
17	 *   node scripts/generate-proto.mjs --check   generate to a temp dir and diff;
18	 *                                             exit non-zero when they differ
19	 */
20	
21	import { execFileSync } from "node:child_process";
22	import { mkdtempSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
23	import { tmpdir } from "node:os";
24	import { dirname, join, resolve } from "node:path";
25	import { fileURLToPath } from "node:url";
26	
27	export const PACKAGE_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
28	
29	const repoRoot = resolve(PACKAGE_ROOT, "..", "..", "..");
30	
31	/**
32	 * The single authoritative contract directory. `crates/aion-proto-generated`
33	 * owns the `.proto` sources the Rust server and Rust worker are built from, so
34	 * generating from anywhere else is how the SDKs drift.
35	 */
36	export const PROTO_DIR = join(repoRoot, "crates", "aion-proto-generated", "proto");
37	
38	/** Only the files the worker SDK needs; the engine's other protos are not ours. */
39	export const PROTO_FILES = ["common.proto", "worker.proto"];
40	
41	/** Where the generated stubs are committed. Every file here is generated. */
42	export const OUTPUT_DIR = join(PACKAGE_ROOT, "src", "proto");
43	
44	/**
45	 * ts-proto options, held here so the recipe is reviewable in one place.
46	 *
47	 * - `esModuleInterop` / `importSuffix=.js`: the package is ESM and compiles
48	 *   with explicit `.js` specifiers on relative imports.
49	 * - `outputServices=grpc-js`: emits the `WorkerProtocolClient` constructor the
50	 *   SDK's default transport wraps. Without it there is no wire client at all.
51	 * - `forceLong=bigint`: `uint64` fields (worker_id, heartbeat_window_ms,
52	 *   sequence_position) become `bigint` rather than a lossy `number` or an
53	 *   extra `long` runtime dependency.
54	 * - `useExactTypes=false`: keeps generated message types structurally
55	 *   assignable from plain object literals, which is what the SDK builds.
56	 */
57	export const TS_PROTO_OPTIONS = [
58		"esModuleInterop=true",
59		"outputServices=grpc-js",
60		"useExactTypes=false",
61		"forceLong=bigint",
62		"importSuffix=.js",
63	].join(",");
64	
65	/** Runs protoc + ts-proto, writing generated stubs into `destination`. */
66	export function generateInto(destination) {
67		mkdirSync(destination, { recursive: true });
68		execFileSync(
69			join(PACKAGE_ROOT, "node_modules", ".bin", "grpc_tools_node_protoc"),
70			[
71				`--plugin=protoc-gen-ts_proto=${join(PACKAGE_ROOT, "node_modules", ".bin", "protoc-gen-ts_proto")}`,
72				`--ts_proto_out=${destination}`,
73				`--ts_proto_opt=${TS_PROTO_OPTIONS}`,
74				"-I",
75				PROTO_DIR,
76				...PROTO_FILES.map((file) => join(PROTO_DIR, file)),
77			],
78			{ stdio: ["ignore", "pipe", "pipe"] },
79		);
80		return destination;
81	}
82	
83	/**
84	 * The `.ts` file names in a directory, sorted. Comparing these sets is what
85	 * catches a file protoc STARTED or STOPPED emitting, and any hand-written
86	 * stray that regeneration could never check.
87	 */
88	export function generatedFileNames(directory) {
89		return readdirSync(directory)
90			.filter((name) => name.endsWith(".ts"))
91			.sort();
92	}
93	
94	/** Generates into a fresh temp directory. The caller owns cleanup. */
95	export function generateIntoTempDir() {
96		return generateInto(mkdtempSync(join(tmpdir(), "aion-worker-proto-")));
97	}
98	
99	/**
100	 * Compares a freshly generated tree against the committed one.
101	 * Returns `{ missing, unexpected, differing }`, all empty when in sync.
102	 */
103	export function compareWithCommitted(fresh) {
104		const freshNames = generatedFileNames(fresh);
105		const committedNames = generatedFileNames(OUTPUT_DIR);
106		const missing = freshNames.filter((name) => !committedNames.includes(name));
107		const unexpected = committedNames.filter((name) => !freshNames.includes(name));
108		const differing = freshNames
109			.filter((name) => committedNames.includes(name))
110			.filter(
111				(name) =>
112					!readFileSync(join(fresh, name)).equals(readFileSync(join(OUTPUT_DIR, name))),
113			);
114		return { missing, unexpected, differing };
115	}
116	
117	function runCli() {
118		const checkOnly = process.argv.includes("--check");
119		const temporary = generateIntoTempDir();
120		try {
121			if (checkOnly) {
122				const { missing, unexpected, differing } = compareWithCommitted(temporary);
123				const problems = [...missing, ...unexpected, ...differing];
124				if (problems.length > 0) {
125					process.stderr.write(
126						`src/proto/ is STALE relative to ${PROTO_DIR}\n` +
127							`  differing: ${differing.join(", ") || "none"}\n` +
128							`  missing from src/proto/: ${missing.join(", ") || "none"}\n` +
129							`  present but not generated: ${unexpected.join(", ") || "none"}\n` +
130							"  the SDK is speaking an older wire contract than the server.\n" +
131							"  run `npm run generate:proto` and commit the result.\n",
132					);
133					process.exitCode = 1;
134					return;
135				}
136				process.stdout.write("src/proto/ matches the authoritative proto contract\n");
137				return;
138			}
139			// Replace only after a successful generation, so a failed protoc run
140			// never leaves src/proto/ half-written.
141			rmSync(OUTPUT_DIR, { recursive: true, force: true });
142			mkdirSync(OUTPUT_DIR, { recursive: true });
143			for (const name of generatedFileNames(temporary)) {
144				writeFileSync(join(OUTPUT_DIR, name), readFileSync(join(temporary, name)));
145			}
146			process.stdout.write(`regenerated src/proto/ from ${PROTO_DIR}\n`);
147		} finally {
148			rmSync(temporary, { recursive: true, force: true });
149		}
150	}
151	
152	if (process.argv[1] === fileURLToPath(import.meta.url)) {
153		runCli();
154	}

